// Transcribed from solid-js@2.0.0-rc.3, the prerelease this repository audits.
// Every name is re-exported by `solid-js`' own `types/index.d.ts` (line 1 from
// `@solidjs/signals`, line 8 from `./client/hydration.js`), and each signature
// is byte-faithful to `@solidjs/signals@2.0.0-rc.3`:
//
// - `untrack`            `dist/types/core/core.d.ts:75`
// - `onCleanup`          `dist/types/signals.d.ts:41`
// - `createMemo`         `dist/types/signals.d.ts:298`
// - `createEffect`       `dist/types/signals.d.ts:367`
// - `createTrackedEffect` `dist/types/signals.d.ts` (the one AfterCall member)
// - `createSignal`       the plain and derived overloads
//
// Nothing on the argument side is reduced: the derived `createSignal` overload
// is kept because 2.0 selects it on `typeof first === "function"` and this
// fixture's whole subject is which wrapper a callback sits under. The option
// objects and inference machinery are reduced; a reduced *result* cannot
// create a callback row.
export type Accessor<T> = () => T;
export type SourceAccessor<T> = () => T;
export type Signal<T> = [Accessor<T>, (next: T) => T];
export type ComputeFunction<Prev, Next extends Prev = Prev> = (previous: Prev) => Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (value: Next, previous: Prev) => void;

export interface Disposable {
  (): void;
}
export interface MemoOptions<T> {
  name?: string;
  equals?: false | ((previous: T, next: T) => boolean);
}
export interface SignalOptions<T> {
  name?: string;
  equals?: false | ((previous: T, next: T) => boolean);
}
export interface EffectOptions {
  name?: string;
  defer?: boolean;
}

export declare function untrack<T>(fn: () => T, strictReadLabel?: string | false): T;
export declare function onCleanup(fn: Disposable): Disposable;
export declare function createMemo<T>(
  compute: ComputeFunction<undefined | T, T>,
  options?: MemoOptions<T>
): SourceAccessor<T>;
export declare const createSignal: {
  <T>(value: Exclude<T, Function>, options?: SignalOptions<T>): Signal<T>;
  <T>(fn: ComputeFunction<undefined | T, T>, options?: SignalOptions<T> & MemoOptions<T>): Signal<T>;
};
export declare function createEffect<T>(
  compute: ComputeFunction<undefined | T, T>,
  effectFn: EffectFunction<T, T>,
  options?: EffectOptions
): void;
export declare function createTrackedEffect<T>(
  compute: ComputeFunction<undefined | T, T>,
  options?: EffectOptions
): void;
